WHERE gl.is_active = 1
AND gl.is_approve = 1
AND gld.is_reconcile = 0
AND gld.credit > 0

  AND gld.company_id = #{filter.companyId}


  AND gld.chart_account_id = #{filter.chartAccountId}


  AND gld.branch_id = #{filter.branchId}




      AND gl.date <= #{filter.dateTo}


      AND gl.date >= #{filter.dateFrom} AND gl.date <= #{filter.dateTo}

mapper.select:
SELECT SUM(debit)-SUM(credit)
  FROM general_ledgers gl
  INNER JOIN general_ledger_details gld ON gl.id=gld.general_ledger_id
  WHERE is_active=1
    AND is_approve=1
    AND is_reconcile=1
    AND company_id=#{filter.companyId}
    AND chart_account_id=#{filter.chartAccountId}

  AND gld.branch_id = #{filter.branchId}
